<?php include __DIR__.'/includes/footer.php'; ?><script>(function(){var f=document.getElementById('review-form'),m=document.getElementById('review-message');if(!f)return;f.addEventListener('submit',async function(e){e.preventDefault();var b=f.querySelector('button');b.disabled=true;m.textContent='Enviando...';try{var r=await fetch('/api/testimonials.php',{method:'POST',body:new FormData(f),headers:{Accept:'application/json'}});var d=await r.json();m.textContent=d.message||d.error||'Resposta recebida.';if(d.ok)f.reset()}catch(err){m.textContent='Não foi possível enviar agora.'}finally{b.disabled=false}})})();</script></body></html>
